import { TRPCError } from "@trpc/server";
import { and, desc, eq, isNotNull, isNull } from "drizzle-orm";
import { z } from "zod";

import { createTRPCRouter, protectedProcedure } from "~/server/api/trpc";
import { item } from "~/server/db/schema";

/**
 * The server cannot read the contents, but it can insist on the envelope shape
 * so a malformed blob never reaches storage: a version tag, the base64url IV
 * and the base64url payload.
 */
const ciphertext = z
  .string()
  .regex(/^v1\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+$/, "malformed ciphertext");

/**
 * Item ids are generated by the client, because an item's ciphertext is bound
 * to its id as AES-GCM additional authenticated data: the id has to exist
 * before the plaintext can be sealed. A client-chosen id is not a client-chosen
 * row — every statement below is scoped to the caller in its WHERE clause, and
 * `create` refuses an id that is already taken rather than writing over it.
 */
const itemId = z.string().uuid();

export const itemRouter = createTRPCRouter({
  list: protectedProcedure.query(async ({ ctx }) => {
    return ctx.db
      .select({
        id: item.id,
        ciphertext: item.ciphertext,
        createdAt: item.createdAt,
        updatedAt: item.updatedAt,
      })
      .from(item)
      .where(and(eq(item.userId, ctx.session.user.id), isNull(item.deletedAt)))
      .orderBy(desc(item.updatedAt));
  }),

  /**
   * Soft-deleted items.
   *
   * Separate from `list` rather than a flag on it, so no caller can
   * accidentally mix deleted rows into the live vault by passing the wrong
   * argument. Without this, `restore` is unreachable and a delete is
   * effectively permanent.
   */
  listDeleted: protectedProcedure.query(async ({ ctx }) => {
    return ctx.db
      .select({
        id: item.id,
        ciphertext: item.ciphertext,
        createdAt: item.createdAt,
        updatedAt: item.updatedAt,
      })
      .from(item)
      .where(and(eq(item.userId, ctx.session.user.id), isNotNull(item.deletedAt)))
      .orderBy(desc(item.updatedAt));
  }),

  create: protectedProcedure
    .input(z.object({ id: itemId, ciphertext }))
    .mutation(async ({ ctx, input }) => {
      const now = new Date();

      // `onConflictDoNothing` is what keeps a guessed id harmless: a collision
      // writes nothing and returns nothing, whoever owns the existing row. The
      // response is the same CONFLICT either way, so it never tells the caller
      // that the id belongs to somebody else.
      const [created] = await ctx.db
        .insert(item)
        .values({
          id: input.id,
          userId: ctx.session.user.id,
          ciphertext: input.ciphertext,
          createdAt: now,
          updatedAt: now,
        })
        .onConflictDoNothing({ target: item.id })
        .returning({ id: item.id });

      if (!created) {
        throw new TRPCError({ code: "CONFLICT", message: "id already in use" });
      }
      return created;
    }),

  update: protectedProcedure
    .input(z.object({ id: itemId, ciphertext }))
    .mutation(async ({ ctx, input }) => {
      // Ownership lives in the WHERE clause. Another user's row is
      // indistinguishable from a row that does not exist.
      const [updated] = await ctx.db
        .update(item)
        .set({ ciphertext: input.ciphertext, updatedAt: new Date() })
        .where(and(eq(item.id, input.id), eq(item.userId, ctx.session.user.id)))
        .returning({ id: item.id, updatedAt: item.updatedAt });

      if (!updated) throw new TRPCError({ code: "NOT_FOUND" });
      return updated;
    }),

  /** Soft delete: the row stays, so a mis-click stays recoverable. */
  delete: protectedProcedure
    .input(z.object({ id: itemId }))
    .mutation(async ({ ctx, input }) => {
      const [deleted] = await ctx.db
        .update(item)
        .set({ deletedAt: new Date() })
        .where(and(eq(item.id, input.id), eq(item.userId, ctx.session.user.id)))
        .returning({ id: item.id });

      if (!deleted) throw new TRPCError({ code: "NOT_FOUND" });
      return deleted;
    }),

  restore: protectedProcedure
    .input(z.object({ id: itemId }))
    .mutation(async ({ ctx, input }) => {
      const [restored] = await ctx.db
        .update(item)
        .set({ deletedAt: null })
        .where(and(eq(item.id, input.id), eq(item.userId, ctx.session.user.id)))
        .returning({ id: item.id });

      if (!restored) throw new TRPCError({ code: "NOT_FOUND" });
      return restored;
    }),
});
